import {readings,wholeReading,ozymandias} from './reading-texts09.js?v=20261028-lit09';
const anthology='https://filestore.aqa.org.uk/resources/english/AQA-8702-TG-POEMS.PDF';
const spec='https://www.aqa.org.uk/subjects/english/gcse/english-8702/specification';
const folger=scene=>`https://www.folger.edu/explore/shakespeares-works/macbeth/read/${scene}/`;
function make(d){
 const topic=d.topic||'power-conflict',id=`lit.${topic==='reading-writing'?'skills':topic}.${d.key}`,ref=topic==='unseen'?'3.2.3':topic==='reading-writing'?'3.3':'3.2.2';
 const full=d.textKeys?.length,quote=d.quote,protectedText=!full&&!quote;
 const qs=(stage,rows)=>rows.map(([prompt,correct,a,b,why,concept],i)=>{const answer=(i+d.key.length)%3,options=[a,b];options.splice(answer,0,correct);return{id:`${id}.${stage}.${i+1}`,prompt,options,answer,why,concept:`lit.${topic==='reading-writing'?'skills':topic}.${d.focus||d.key}.${concept}`};});
 const contextReading=[...(d.textKeys||[]).map(k=>({url:readings[k].url,label:`${readings[k].title} · ${readings[k].author}`})),...(d.contextReading||[])];
 return {id,topicId:`english-literature.${topic}`,title:d.title,scope:d.scope,minutes:d.minutes||25,refs:ref==='3.3'?['3.3']:[ref,'3.3'],author:d.author||'Selected poets',rights:protectedText?'protected_summary_only':'public_domain',textType:quote?'play':'poem',textTitle:d.scope,readingURL:d.readingURL||(full?readings[d.textKeys[0]].url:quote?d.sources[0]:`${anthology}#page=${d.page||21}`),sources:[spec,...new Set([...(d.sources||[anthology]),...contextReading.map(r=>r.url)])],contextReading,
 sourceNote:d.sourceNote||(full?(d.textKeys.map(k=>`${readings[k].title} — ${readings[k].author}. ${readings[k].note}`).join(' ')+' These are unfamiliar-reading practice texts, not AQA set poems or official examination questions.'):'Original commentary on the named assigned poems; no protected poem passage reproduced. Read both assigned texts for exact evidence. Supported interpretations may differ.'),
 explorerNote:full?'Complete public-domain poem text with original teaching commentary. Source and edition details are in Sources & notes.':d.explorerNote||undefined,
 cards:d.cards,views:[{kind:'language',label:full?(d.textKeys.length>1?'Read the poems':'Read the poem'):quote?'Read closely':'Poem lenses',title:full?d.scope:quote?'Selected textual evidence':'Original teaching commentary · not a poem quotation',content:full?wholeReading(...d.textKeys):quote||d.summary,words:d.details,...(protectedText?{originalSummary:true,textType:'poem'}:{}),...(full?{fullText:true}:{})},{kind:'people',label:d.perspectiveLabel||'Perspectives',title:'Compare positions',rows:d.people},{kind:'timeline',label:d.movementLabel||'Build the argument',title:'Trace the reasoning',events:d.movement}],
 tasks:[[d.challenge[0],d.challenge.slice(1,4),0,d.challenge[4],d.challenge[5]]],practice:qs('practice',d.practice),check:qs('check',d.check),writing:d.writing,rubric:d.rubric,...(d.independent||{})};
}
export const batch09=[
make({key:'poem-14-2',focus:'history',title:'Checking Out Me History · Language, form, structure and comparison',scope:'Checking Out Me History',author:'John Agard',page:39,
 cards:[['Listen for competing patterns','Recall the speaker’s challenge to selective teaching. A recurrent account of what others tell him is interrupted by more sustained attention to sidelined figures. Read the assigned poem aloud and compare the sound and shape of these passages. Repetition establishes a pressure that another kind of telling can answer.'],['Treat voice and layout as choices','The Creole voice carries intellectual authority. Changing line lengths and the printed distinction between historical portraits can direct emphasis. Analyse a local image of sight or light alongside the exclusion it challenges. Do not treat non-Standard English as evidence of confusion, or typography as decoration detached from the argument.'],['Compare the work of identity','The Emigrée also connects identity and language, but its remembered belonging differs from this active recovery of historical knowledge. Compare what the speakers preserve or reclaim, then explain a difference in how their voices organise that work. Neither poem is a complete neutral history or a report of every migrant’s experience.']],summary:'Competing patterns of telling make selection visible. Voice, sound and visual emphasis help turn inherited exclusion into active historical inquiry.',details:[['Repeated account','A recurrent imposed version becomes a pattern to resist.'],['Recovered portraits','Different visual and rhythmic treatment can redirect attention.'],['Vision and light','Images can connect knowledge with the power to recognise identity.']],people:[['Received account','Selects what a learner is told.'],['Speaking investigator','Uses a distinct voice to reclaim agency.'],['Emigrée comparison','Preserves remembered belonging rather than following the same historical inquiry.']],movement:[['Pattern','Establish the inherited account.'],['Interruption','Give sidelined figures attention.'],['Contrast','Compare the forms of telling.'],['Agency','Explain who now investigates.']],challenge:['Which reading connects form with the argument?','Contrasting patterns of telling challenge who controls historical attention.','Creole proves the speaker cannot develop an argument.','Different line lengths make historical selection irrelevant.','The method matters through its contribution to the struggle over knowledge.','Ask whose version gains space and authority, not which voice needs correcting.'],practice:[['Why compare repeated passages with the portraits?','Their contrast shows a struggle over attention and authority.','They prove every named figure has the same history.','Only the poem’s date can explain its meaning.','Structure organises the competing kinds of account.','structure'],['What strengthens analysis of a light image?','Explain its connection with knowledge in that passage.','Say light always guarantees a happy ending.','Name imagery and move on.','An image needs a local relation to the poem’s argument.','methods'],['How does comparison with The Emigrée become precise?','Distinguish active recovery from persistent remembered attachment.','Identify the unnamed city as Agard’s school.','Treat both speakers as the same person.','A common concern develops through different acts and voices.','comparison']],check:[['What does the changing shape of the portraits allow?','A shift of emphasis towards previously sidelined lives.','A complete neutral textbook of every event.','Proof that sound has no relevance.','Visual organisation can redistribute attention.','structure'],['Which statement respects linguistic choice?','Creole can carry the authority of a crafted argument.','Only formal Standard English can analyse identity.','Dialect means the poet has lost control.','Evaluate what the voice does rather than disqualify it.','voice'],['Which claim about a device needs correction?','A repeated phrase must have the same effect in every context.','A recurring account can become something to resist.','A contrast can sharpen a dispute over authority.','Effects depend on the surrounding argument and change.','methods'],['What should a comparison retain?','Differences in the speakers’ work of preserving or reclaiming identity.','An assumption that both poems have identical situations.','Only a list of shared devices.','Relation and distinction both contribute to a critical comparison.','comparison']],writing:'Compare how Checking Out Me History and The Emigrée connect language with identity. Analyse contrasting patterns of voice and explain a difference between recovery and preservation.',rubric:['Support a comparative claim with accurate references to both assigned poems.','Analyse voice, structure or imagery through the work it performs.','Respect Creole and preserve differences between the speakers’ situations.'],contextReading:[{url:'https://poetryarchive.org/poem/checking-out-me-history/',label:'John Agard · authorised reading'}]}),
make({key:'poem-15-1',focus:'kamikaze',title:'Kamikaze · Meaning, voice and movement',scope:'Kamikaze',author:'Beatrice Garland',page:41,
 cards:[['Distinguish the layers of telling','A daughter recounts a father who returned from a mission intended to end in his death. Parts of the flight are imagined through her later account. As you read the whole poem, separate what the family says happened from what the daughter thinks he may have seen or remembered. The poet is not the pilot or his daughter.'],['Read the possible motive carefully','Images of sea life and childhood open a way to imagine why he turned back. The account does not give direct access to his private thoughts. A response can argue that ordinary life challenges military duty, while qualifying the claim as an inference mediated by the daughter’s telling.'],['Survival is followed by exclusion','The pilot returns alive, but family and neighbours withhold ordinary recognition. Even the children learn the silence. The ending places survival beside a different kind of loss; it does not say that returning is the same as literally dying. Context helps explain a pressure without making all Japanese families or people identical.']],summary:'A narrated return preserves physical life but brings social exclusion. The daughter’s account imagines a motive while withholding complete access to the father.',details:[['Reported return','A physical return is distinguished from social acceptance.'],['Imagined view','The daughter reconstructs what he might have seen.'],['Learned silence','Children acquire the community’s exclusionary behaviour.']],people:[['Father','Returns, but does not explain his thoughts directly.'],['Daughter','Recounts events and imagines part of the flight.'],['Family and neighbours','Impose or learn a silence that changes relationships.']],movement:[['Departure','A mission is presented as one way.'],['Imagining','Sea life and childhood enter the account.'],['Return','Survival meets rejection.'],['Question','The ending weighs different kinds of loss.']],challenge:['Which claim distinguishes fact and inference?','His return is reported, while his precise motive is imaginatively reconstructed.','He dies during the flight and never returns.','The father tells every thought directly to the reader.','Narrative mediation limits certainty about another person’s inner life.','Separate the reported outcome from the daughter’s imagined explanation.'],practice:[['What happens to the pilot?','He returns alive.','He is explicitly killed before returning.','He becomes the editor of a newspaper.','The later rejection depends on his physical return.','meaning'],['Why attend to the daughter’s reconstruction?','It shapes the reader’s access to a possible motive.','It proves she was in the aircraft.','It removes the need for inference.','A later account can imagine what it cannot directly witness.','methods'],['What do the children gradually learn?','To participate in the silence around their father.','To restore the earlier relationship immediately.','That the pilot never existed literally.','The community’s behaviour becomes learned within the family.','relationships']],check:[['What tension develops after return?','Physical survival coexists with exclusion from ordinary recognition.','Everyone celebrates and no tension remains.','The father becomes the first-person narrator throughout.','The poem distinguishes biological survival and social belonging.','movement'],['Which claim overstates the account?','We know the father’s exact thoughts from his own uninterrupted speech.','The daughter mediates part of the story.','A reader can infer that memories of life matter.','A reconstructed motive should not be called direct testimony.','voice'],['How can context be used responsibly?','Explain pressures on the pilot without generalising about every Japanese person.','Replace analysis with a universal national stereotype.','Treat the poem as a complete historical survey.','Context illuminates a particular narrative rather than erasing differences.','context'],['What does the ending invite?','A comparison of survival with another form of loss.','A literal statement that the living pilot never returned.','A guarantee that exclusion has ended.','An unresolved question keeps the costs of return in view.','interpretation']],writing:'How does Garland present the consequences of the pilot’s return in Kamikaze? Analyse the daughter’s account and distinguish a possible motive from an explicitly reported event.',rubric:['Trace the difference between physical return and social exclusion.','Support an interpretation through voice and precise assigned-text detail.','Qualify inferred motives and avoid national stereotypes.']}),
make({key:'poem-15-2',focus:'kamikaze',title:'Kamikaze · Language, form, structure and comparison',scope:'Kamikaze',author:'Beatrice Garland',page:41,
 cards:[['Read continuity and division together','Kamikaze has seven six-line stanzas, with sentences and imagined movement passing across line boundaries. Trace a sentence rather than assuming each stanza contains a separate event. A regular visible pattern can contain changing relationships and unresolved pressure; it is not proof of emotional calm.'],['Listen for the family voice','The movement from a reported father and daughter towards the daughter’s family perspective changes the distance of the telling. Expansive images of living things contrast with later silence. Ask how much space the imagined experience receives and how ordinary recognition is then withheld. No single image gives a complete explanation of the pilot.'],['Compare duty under pressure','Bayonet Charge focuses on a running soldier’s bodily experience as public ideals lose their immediate force. Kamikaze reconstructs a decision and its consequences through later family narration. Compare how the poems put life and duty under pressure, while retaining different voices, actions and outcomes.']],summary:'An orderly stanza frame contains a changing distance from the family story. Flowing images of life encounter the restriction of learned silence.',details:[['Seven sestets','A repeated frame holds changes in voice and focus.'],['Narrative distance','A later family voice changes our relation to the account.'],['Life and silence','Contrasting imagery and response test ideas of honour.']],people:[['Imagined pilot','Appears through the daughter’s reconstruction.'],['Family voice','Makes the cost of exclusion immediate.'],['Bayonet soldier','Experiences a different crisis through bodily focalisation.']],movement:[['Frame','Establish a mission and reported relationship.'],['Expansion','Give space to imagined life and memory.'],['Shift','Bring the family’s response closer.'],['Question','Leave the competing losses unresolved.']],challenge:['Which comparison explains different methods?','Later family narration differs from the bodily focalisation of a soldier in action.','Both poems are direct speeches by the same pilot.','Seven sestets prove the family is content.','Related pressures are organised through distinct narrative distances.','Compare how readers gain access to experience, not only the shared idea of duty.'],practice:[['Which stanza arrangement is accurate?','Seven sestets.','Four quatrains and a single line.','A single fourteen-line sonnet.','A sestet is a six-line stanza, not a guaranteed emotional effect.','form'],['Why analyse flowing sea imagery beside later silence?','Their contrast develops a tension between life and social rejection.','It proves the daughter was on the flight.','It means silence must be a literal absence of sound everywhere.','Contrast gains meaning through the changing human relationships.','methods'],['What differs from Bayonet Charge?','Kamikaze mediates a return through a later family account.','Both poems have identical outcomes and narrators.','Bayonet Charge supplies the pilot’s lost diary.','Keep action, outcome and narration distinct.','comparison']],check:[['What can change inside a regular stanza pattern?','Perspective, pace and emotional pressure.','Nothing: regular stanzas force a single emotion.','Only the author’s biography.','Visible order does not cancel shifts in the telling.','form'],['Which question helps analyse a voice shift?','How does the change alter the distance between reader and family experience?','Which pronoun always guarantees truth?','Does first person mean the poet experienced every event?','Voice concerns access and presentation, not automatic reliability.','voice'],['How can the two conflict poems be related?','Both test duty against life through different situations and perspectives.','Both depict the same named mission.','Both prove every soldier has the same response.','A meaningful comparison includes a significant difference.','comparison'],['What should an analysis of enjambment explain?','What this sentence does as it crosses a particular boundary.','A fixed rule that every broken line means fear.','Why all stanza divisions disappear.','Link syntax and line locally rather than impose a universal code.','methods']],writing:'Compare how Kamikaze and Bayonet Charge present duty under pressure. Explain how narrative distance, imagery and the movement of each poem shape the reader’s response.',rubric:['Compare a significant pressure while distinguishing actions and outcomes.','Analyse a precise linguistic or structural choice in both poems.','Explain narrative access without equating speaker, character and poet.']}),
make({key:'comparison-01',title:'Power and authority',scope:'My Last Duchess / Ozymandias',
 cards:[['Start with a relation that can be tested','Both poems expose a powerful man’s self-presentation, but they make him available differently. Browning gives the Duke an extended living speech; Shelley gives a framed account of a damaged representation. A useful thesis can connect the wish to control reputation with the way the poem makes that wish unstable.'],['Pair evidence by what it does','Select a precise detail from each assigned poem that addresses self-presentation. Then compare the Duke’s attempt to guide a listener with the ruler’s surviving claim. Do not write two isolated mini-essays and add a connecting word afterwards. Make the relation clear at the level of voice, art or structure.'],['Qualify the argument','The Duke still negotiates within a living social order; the monument stands in a landscape of ruin. That difference limits a claim that all power has already vanished in both poems. Comparison can expose a shared insecurity while recognising that authority operates on different timescales.']],summary:'Compare the work of self-presentation through two different encounters: an active controlling voice and a surviving ruined image.',details:[['Narrative frame','Who carries the powerful man’s representation to us?'],['Claim and implication','What is asserted, and what can the reader infer?'],['Different survival','How much power still operates within the scene?']],people:[['Duke','Directs an encounter and a marriage negotiation.'],['Ozymandias','Survives through an image and a reported claim.'],['Reader','Judges how representation can undermine intention.']],movement:[['Thesis','Relate the wish to control reputation.'],['Evidence','Select a detail from each poem.'],['Analysis','Explain different means of self-presentation.'],['Qualification','Distinguish living authority from ruin.']],challenge:['Which thesis is most defensible?','Both expose self-presentation, but power survives differently in each encounter.','Both rulers have already lost every form of power.','Both poems use one identical speaker.','A thesis needs both a relation and a difference the evidence supports.','Test the claim against the Duke’s ongoing negotiation as well as the ruined statue.'],practice:[['What is a useful shared focus?','The attempt to control how power is represented.','The claim both scenes occur in one desert.','The number of letters in each ruler’s name.','A shared concern must permit analysis of choices in both poems.','focus'],['Which pairing develops method?','Living monologue beside a framed report of a monument.','Two unrelated biographies with no textual analysis.','Only the fact that both poets use words.','Voice and frame shape readers’ access to authority.','methods'],['What qualifies a claim of total loss?','The Duke still acts within an ongoing negotiation.','Every speaker explicitly dies during the poem.','The poems have the same setting.','A significant difference can sharpen rather than destroy a comparison.','qualification']],check:[['Which outline is comparative?','A shared claim, linked evidence and an explained difference.','One summary followed by another with no relation.','A list of devices with no meanings.','Organisation should keep the question and the relation visible.','argument'],['Why compare intention and effect?','A representation can disclose more than a ruler intends.','The ruler’s own praise must be the poet’s final judgment.','Reader inference is forbidden in poetry.','A voice can reveal assumptions that readers question.','voice'],['What needs correcting?','The Duke and Ozymandias exercise identical power at the moment of reading.','Art can expose a claim to authority.','A reader can compare how voice works.','Different narrative situations limit simple equivalence.','difference'],['What best supports a conclusion?','Return to the precise relation and its qualification.','Introduce an unsupported claim about every ruler in history.','Repeat a technique list without reasoning.','A conclusion should refine the argument the evidence has developed.','argument']],writing:'Compare how My Last Duchess and Ozymandias expose the self-presentation of powerful men. Build a connected argument about voice and representation, including a significant difference.',rubric:['Maintain a shared focus that answers the comparison question.','Analyse linked evidence from both assigned poems.','Qualify the relation through the different operation or survival of power.']}),
make({key:'comparison-02',title:'Power of nature',scope:'Extract from The Prelude / Storm on the Island',
 cards:[['Compare the changing relationship','The Prelude extract revisits an individual experience that unsettles confidence. Storm on the Island develops a communal explanation that encounters fear. Start with the relationship between human assurance and a pressure that resists it; then ask how each voice changes rather than reducing both poems to a single emotion.'],['Explain scale and access','Use the assigned texts to compare a feature that changes the scale of the natural world and a feature that makes unseen pressure imaginable. Read simile, personification or metaphor through the perspective producing it. Figurative agency does not prove nature literally plans an attack.'],['Keep endings in the argument','A later troubled memory and a communal statement of fear give the encounters different shapes. Explain what remains unsettled. A political interpretation of Storm may be argued with evidence, but it should not erase the physical storm or turn a title resemblance into proof of one compulsory allegory.']],summary:'Individual recollection and communal explanation both test human assurance. Compare the forms of uncertainty they leave behind.',details:[['Perspective','Who encounters nature, and from what later position?'],['Figurative scale','How does imagery make power felt?'],['Unsettled ending','What remains beyond confident explanation?']],people:[['Remembering individual','Revisits a formative disturbance.'],['Communal speaker','Offers and qualifies shared assurances.'],['Reader','Tests figurative meanings without making them literal facts.']],movement:[['Relation','Human assurance meets pressure.'],['Method','Pair evidence about scale or threat.'],['Voice','Explain the different access to experience.'],['Ending','Compare what remains unsettled.']],challenge:['Which claim preserves both poems’ perspectives?','Individual recollection and communal explanation organise different encounters with natural power.','Both speakers give the same eyewitness report.','Personification proves nature literally intends revenge.','A shared concern can be developed through different voices and times.','Ask whose assurance changes, and how the telling lets us observe that change.'],practice:[['Which shared concern is precise?','Human confidence becomes difficult to sustain.','Every natural image means literal military invasion.','Both narrators are identical to their poets.','Describe a relationship and change rather than a vague topic.','focus'],['How should a figurative threat be analysed?','Explain how the speaker imagines pressure through a particular comparison.','Assume the metaphor documents a literal army.','Ignore the surrounding perspective.','An image gives a way of understanding experience.','methods'],['What should an alternative political reading do?','Remain supported and preserve the poem’s physical scene.','Replace every textual detail with a title pun.','Become compulsory without evidence.','Contextual possibilities need an argument and limits.','interpretation']],check:[['What differs in the framing of experience?','Later individual memory and a communal conversational account.','Two identical speeches by one soldier.','Two reports naming the same battlefield.','Voice and time affect how power is presented.','voice'],['Which comparison is analytical?','Relate two images to the different kinds of uncertainty they produce.','State both contain nature and stop.','Count nouns without explaining choices.','A connection needs method and meaning.','methods'],['What is a defensible ending claim?','Both leave a pressure that confidence does not fully master.','Both guarantee complete lasting control over nature.','Both explicitly ban all future boats and houses.','Do not turn a complex closing response into an invented policy.','ending'],['Why avoid a fixed rule for personification?','Its effect depends on the speaker and surrounding passage.','It has no meaning in any poem.','It always proves a supernatural being is present.','A term names a method; analysis explains this use.','methods']],writing:'Compare how the Prelude extract and Storm on the Island unsettle confidence in human control. Analyse imagery, voice and an ending, explaining a meaningful difference.',rubric:['Define the changing human–nature relationship in both poems.','Explain precise methods through their different perspectives.','Preserve ambiguity and qualify literal or political claims.']}),
make({key:'comparison-03',title:'Experiences of conflict',scope:'The Charge of the Light Brigade / Bayonet Charge',
 cards:[['Distinguish public tribute from immediate experience','Tennyson’s collective riders enter a public act of remembrance; Hughes’s focal soldier runs amid bodily shock. Both concern military action, but different distances organise it. Form a claim about how soldiers relate to command or ideals, not a blanket statement that every war poem makes the same judgment.'],['Compare movement rather than count rhythm','Read a passage of riding beside a passage of running. Ask how rhythm, repetition, syntax and pauses shape each action. A repeated strong beat can gather a group; a broken or suspended moment can isolate a consciousness. Support these possibilities through the actual lines rather than a formula about fast and slow poetry.'],['Separate admiration and authority','Honouring courage does not automatically approve the decision behind a charge. A soldier’s urgent fear does not establish that every public ideal is meaningless in every context. A qualified comparison can test what each poem makes available to admire, question or experience. Historical context locates the poems without replacing their choices.']],summary:'Public collective commemoration and immediate bodily focalisation offer different access to military action and the ideals surrounding it.',details:[['Distance','Public tribute differs from a moment of bodily crisis.'],['Movement','Rhythm and syntax organise riding or running.'],['Competing values','Courage, command and survival need not be judged identically.']],people:[['Collective riders','Are narrated and commemorated as a group.'],['Focal soldier','Experiences a frightening immediate action.'],['Public reader','Is invited into different relations of admiration or pressure.']],movement:[['Question','Define an aspect of military experience.'],['Pair','Relate precise movement details.'],['Analyse','Explain narrative distance and form.'],['Qualify','Separate courage, command and ideals.']],challenge:['Which comparative claim handles judgment carefully?','Different distances can honour a group or expose bodily pressure without making every military decision identical.','Both poems prove every order deserves unquestioning approval.','Both poems must condemn all courage as worthless.','Distinguish the conduct of soldiers from commands and public ideals.','Ask who is admired or questioned and how the reader encounters their experience.'],practice:[['What is a significant difference in access?','Collective public narration versus an individual’s focal experience.','Two identical private diaries.','An editor versus a parent at a memorial.','Narrative distance changes how the action is understood.','voice'],['What makes a movement comparison precise?','Link a rhythm or sentence pattern to the experience it shapes.','State both contain verbs and stop.','Give metre a fixed moral meaning.','A formal observation needs an explained local effect.','methods'],['Which distinction matters to judgment?','Admiring courage differs from approving the order.','Every soldier and commander has the same responsibility.','Honour rules out any recognition of error.','Actions, roles and decisions should be separated.','judgment']],check:[['How can a thesis move beyond war as a topic?','Explain different relations between military ideals and lived action.','Announce both poems contain soldiers and end there.','Retell each plot without a shared question.','A thesis proposes a relation the evidence can develop.','argument'],['Which statement overclaims?','A panicked moment proves no soldier ever holds any ideal.','Bodily focalisation can pressure abstract values.','A tribute can coexist with acknowledged error.','A particular represented experience is not universal proof.','interpretation'],['What should historical context support?','Analysis of a specific choice or pressure in the poem.','Replacement of the poem with a battle chronology.','The assumption that both poets were eyewitnesses.','Context informs interpretation when connected to textual evidence.','context'],['Which conclusion follows a developed comparison?','Different voices make courage and fear available in different ways.','All conflict poems have an identical meaning.','A shared word proves identical authorial intention.','A conclusion can draw together a relation while preserving distinctions.','comparison']],writing:'Compare how The Charge of the Light Brigade and Bayonet Charge present soldiers’ experiences. Analyse movement and narrative distance, distinguishing courage, command and ideals.',rubric:['Develop a comparison about experience rather than a generic view of war.','Connect specific formal choices to the reader’s access in both poems.','Qualify judgments about courage, command and survival.']}),
make({key:'comparison-04',title:'Memory and consequences',scope:'Poppies / War Photographer',
 cards:[['Define the different relationships','Poppies presents a parent’s absence and remembered care; War Photographer follows a worker’s relation to recorded suffering and its audience. Both place private experience beside public remembrance or representation. Start with those different roles before proposing a relation about how conflict reaches beyond the original event.'],['Let an image develop the comparison','Choose one domestic or memorial image and one photographic or darkroom image in the assigned poems. Explain how each connects a present act with another time or person. Avoid merely matching colours: the same visual property can participate in very different emotional and ethical relationships.'],['Preserve what is not settled','Poppies does not explicitly confirm the child’s death. Duffy’s judgment about public response is a literary challenge rather than a survey of every reader. Qualification makes the comparison more accurate. It allows an argument about unresolved attachment and responsibility without inventing facts to make both poems the same.']],summary:'Memory connects different present acts to absent people. Compare parenthood and professional witnessing without erasing uncertainty or mediation.',details:[['Roles','Absence in a family differs from professional witnessing.'],['Present action','Care, walking or developing an image can activate another time.'],['Limits','An unresolved fate and a poetic audience judgment require qualification.']],people:[['Parent','Addresses an absent child through memory.'],['Photographer','Works with images of other people’s suffering.'],['Audience','Receives different invitations to remember or respond.']],movement:[['Define','Name the different relationship in each poem.'],['Connect','Pair images that activate memory.'],['Explain','Relate present acts to absence.'],['Qualify','Retain uncertainty and mediated knowledge.']],challenge:['Which claim keeps the roles and evidence distinct?','Both connect present experience to absent people, but parent and witness have different relationships.','Both speakers are parents whose children are confirmed dead.','Every image proves that all readers respond identically.','Comparison should not create certainty or equivalence absent from the texts.','Name who remembers whom and what the account does not establish.'],practice:[['What is a productive shared focus?','The continuing pressure of absent lives on present experience.','The proof that both speakers took the same photograph.','The belief that absence always means confirmed death.','A related pressure can occur through different roles.','focus'],['What makes an image pairing analytical?','Explain how each image connects a present act to another time or person.','Match two colours and claim identical meanings.','List quotations without a relation.','The comparison needs the work an image does in context.','methods'],['Which claim about Poppies needs correction?','The memorial explicitly confirms the child’s death.','Remembrance symbols shape the parent’s experience.','The parent’s voice can contain mixed feelings.','Suggested loss is not a complete factual report.','inference']],check:[['What should an opening comparison establish?','The related concern and different speaker relationships.','That both poems describe the same child.','A compulsory single emotional response.','Define the relation without flattening the situations.','argument'],['How should public response in War Photographer be treated?','As a critical poetic presentation, not a universal measurement.','As a statistical conclusion about every newspaper reader.','As direct speech from every photographed person.','Literary judgment and empirical proof are different kinds of claim.','voice'],['Which method can connect present and past?','A present image or action that prompts recollection.','Only the poet’s birth date.','Any rhyme regardless of context.','Explain the temporal work of the particular choice.','methods'],['What makes a qualification useful?','It limits the thesis to what each poem supports.','It removes the need to make an argument.','It proves all interpretations are equally evidenced.','Qualified claims can be both clear and precise.','interpretation']],writing:'Compare how Poppies and War Photographer connect present acts with absent people. Analyse imagery and the movement of memory, preserving differences in roles and knowledge.',rubric:['Connect a sustained concern with the different relationships in each poem.','Explain temporal or visual methods through precise assigned-text evidence.','Preserve uncertainties rather than invent a shared biography.']}),
make({key:'comparison-05',title:'Identity and belonging',scope:'The Emigrée / Checking Out Me History',
 cards:[['Make language the basis of the relation','Both poems connect a voice with a contested account of identity. Rumens’s speaker carries a remembered place and language; Agard’s investigates omissions in an inherited education. Develop the comparison around what each voice preserves or reclaims. A broad shared theme becomes useful when it leads to a different action.'],['Compare a pattern, not a stereotype','Trace recurring brightness in The Emigrée beside a repeated taught account and recovered portraits in Checking Out Me History. Ask how each pattern meets pressure. Avoid converting the voices into a generic account of all migrants or all Caribbean people. Creole remains a deliberate expressive choice, not a deficiency.'],['Use the ending to test the thesis','Persistent memory and active inquiry offer different resources for belonging. Neither supplies a finished objective history or guarantees the disappearance of hostility. A conclusion can argue that identity is sustained through particular acts of language while retaining the unresolved pressures each poem presents.']],summary:'Preservation and recovery offer related but distinct ways of shaping identity through language under pressure.',details:[['Preserve or reclaim','Name the different work performed by the voices.'],['Recurring patterns','Compare how repetition meets resistance.'],['Continuing pressure','Agency need not remove every constraint.']],people:[['Remembering speaker','Carries an unnamed city into present life.'],['Investigating speaker','Challenges omissions and reclaims attention.'],['Reader','Tests agency without reducing people to a stereotype.']],movement:[['Relation','Connect language and contested identity.'],['Distinction','Name preservation and recovery.'],['Methods','Compare recurring patterns in context.'],['Ending','Test what changes and what persists.']],challenge:['Which thesis preserves a significant difference?','Language sustains identity through remembered attachment in one poem and active recovery in the other.','Both speakers identify the same city and school.','Creole makes identity impossible to analyse.','A common concern is sharpened by different acts and situations.','Ask what each speaker does with language rather than assume identical experience.'],practice:[['Which contrast can develop the argument?','Remembered attachment beside investigation of excluded history.','The assumption that both speakers share one nationality.','Only the fact both poems have titles.','A meaningful distinction can organise a comparative paragraph.','focus'],['How should recurring patterns be compared?','Explain how each pattern responds to a particular pressure.','Give every light image and refrain one identical effect.','Replace method with a stereotype.','Repetition needs the context of the voice and its conflict.','methods'],['What remains at the ending?','Agency or attachment can coexist with continuing constraints.','A complete end to every political and social conflict.','A verified objective account of all history.','An ending need not remove the pressures that give agency meaning.','ending']],check:[['What does the unnamed city require?','Avoid imposing a location as if it were stated.','Identify it as Agard’s named school.','Ignore all spatial imagery.','Interpret the details without inventing geographical certainty.','inference'],['Which statement respects the voice?','Creole contributes to a deliberate challenge to authority.','Creole is proof of failed poetic control.','Only formal Standard English can express a critical argument.','Linguistic choice participates in the question of whose knowledge counts.','voice'],['What makes a comparison paragraph coherent?','A shared focus developed through linked evidence and a difference.','A sequence of unrelated historical facts.','Two isolated summaries with no relation.','The paragraph must make the relation explicit.','argument'],['What should a concluding claim avoid?','Generalising from two crafted speakers to every migrant’s experience.','Explaining how language sustains identity.','Preserving a difference between remembering and inquiry.','A literary comparison should remain proportional to its evidence.','interpretation']],writing:'Compare how The Emigrée and Checking Out Me History present language as a resource for identity. Analyse recurring patterns and voice, distinguishing preservation from recovery.',rubric:['Maintain a comparative focus on the work of language.','Analyse linked evidence from the assigned poems rather than list themes.','Preserve different experiences and qualify claims about agency or belonging.']}),
make({key:'comparison-06',title:'Independent anthology comparison and revision',scope:'Planning model: Exposure / The Charge of the Light Brigade',
 cards:[['Choose evidence after reading the question','For a model comparison about soldiers’ experience, Exposure and The Charge of the Light Brigade allow waiting to be set beside movement. Write a one-sentence relation before selecting evidence. This is a planning model, not the answer to the independent task: that task supplies a different named poem.'],['Build a line of reasoning','Plan two or three connected claims, each linking method and meaning in both poems. A paragraph should move the overall answer forward rather than repeat the same observation with a new quotation. The number is a planning aid, not a required formula. Leave room to qualify an interpretation.'],['Revise an argument rather than polish a score','After a first response, test each paragraph against its claim: does the evidence support it, and is the comparison explained? Preserve the submitted version and revise separately. Knowledge choices cannot establish essay attainment. The independent workspace hides this guidance and review criteria until submission; external resources cannot be policed.']],summary:'A question-led plan connects claims, evidence, method and qualification. Independent writing is recorded separately from knowledge checks.',details:[['Question focus','Let the wording determine what evidence is relevant.'],['Line of argument','Make each paragraph develop the answer.'],['Revision','Change reasoning where evidence does not support it.']],people:[['Writer','Chooses and explains a relation.'],['Critical reader','Tests whether evidence warrants each claim.'],['Teacher','Reviews actual writing rather than inferring attainment from clicks.']],movement:[['Read','Define the task precisely.'],['Plan','Connect a small set of claims.'],['Write','Explain method and relation through evidence.'],['Review','Preserve the first response and revise separately.']],challenge:['Which plan supports a comparative argument?','Connected question-led claims with evidence and explanation from both poems.','A memorised essay used regardless of the task.','A fixed device list without a developing answer.','Planning is a way to reason about this question, not bypass it.','Test whether every planned paragraph moves the specific answer forward.'],practice:[['What should be decided before collecting quotations?','The precise focus of the question and a tentative relation.','A fixed grade the essay must receive.','The longest quotation available.','Relevance depends on the argument the task asks for.','planning'],['How should methods be included?','Explain how a particular choice develops the comparison.','Name every term regardless of relevance.','Use terminology as a substitute for meaning.','A term is useful when it helps explain the text.','methods'],['What makes revision substantive?','Changing a claim or reasoning when the evidence requires it.','Only adding impressive adjectives.','Deleting the first submission so no change can be seen.','Revision should improve support and coherence while preserving the record.','revision']],check:[['Which plan develops rather than repeats?','Each linked claim adds a new reason for the overall answer.','Every paragraph repeats one point with a different quotation.','The answer never returns to the question.','A sustained argument has direction and progression.','argument'],['What should a chosen comparison poem offer?','Relevant evidence and methods for the particular task.','Only a similar title.','A guarantee that every interpretation is identical.','Choose by the relation the evidence can support.','selection'],['When should review criteria guide revision?','After the unassisted first response is submitted.','By replacing the response with a copied model answer.','By treating selected-response success as a writing mark.','Separate initial performance from later supported improvement.','independence'],['Which limitation must a result retain?','Knowledge scores do not establish essay mastery.','Saving a draft proves it is correct.','Opening a reading view earns a GCSE writing grade.','Actual writing needs review against the relevant criteria.','assessment']],writing:'Plan a comparative answer about how soldiers experience conflict in Exposure and The Charge of the Light Brigade. Use the independent workspace for the separate assessed-style practice task.',rubric:['Answer the actual comparison question through a sustained relation.','Analyse accurate evidence and method in the supplied poem and one other studied poem.','Develop a meaningful difference and revise clarity, grammar and support.'],independent:{independentWriting:true,independentTaskType:'anthology-comparison',independentIntro:'Compare the supplied named poem with one other poem you have studied. Only the named poem is supplied.',independentTaskLabel:'A named-poem comparison with one other studied poem.',independentPrompt:'Compare how poets present the power of human beings in Ozymandias and in one other poem from Power and Conflict. Write a connected argument using evidence and methods from both poems. This is original practice, not an official exam paper.',independentExtractLabel:'Ozymandias — Percy Bysshe Shelley · complete public-domain poem',independentExtract:ozymandias}}),
make({topic:'unseen',key:'lesson-01',title:'First reading and literal meaning',scope:'Adlestrop',author:'Edward Thomas',textKeys:['adlestrop'],
 cards:[['Establish what happens before interpreting','Read Adlestrop once without hunting for devices. A speaker remembers a train stopping at a place in June; attention moves from the platform into the surrounding landscape and sound. Write one plain sentence about the situation. An accurate first account gives later interpretation something to test. Unwontedly means unusually; a haycock is a small pile of hay.'],['Separate observation and response','The speaker reports little human movement but remembers an expanding field of birdsong. A possible reading values a moment of attention within travel. Do not claim the speaker has scientifically counted every bird in two counties: poetic expansion presents the reach of perception, not a census.'],['Read again to test the first account','Mark a word or boundary that complicates your summary. The remembered name can be sparse at first, then gather sensory associations. Explain how the ending changes the scale of the experience. A title is a starting point for inquiry, not a complete interpretation; unfamiliar words can be checked without surrendering your own reading.']],details:[['Yes. I remember','A conversational assertion places the event inside recollection.'],['No one left and no one came','Little outward human action leaves room for attentive perception.'],['Farther and farther','Repetition expands the remembered field of sound.']],people:[['Remembering speaker','Selects what remains significant from the stop.'],['People at the station','Appear briefly within an otherwise quiet scene.'],['Reader','Distinguishes a recalled experience from a complete factual record.']],movement:[['Orient','Identify place, time and speaker.'],['Summarise','State the literal stop in plain language.'],['Notice','Track the shift in attention.'],['Interpret','Test a claim against the widening ending.']],challenge:['Which first account is accurate and proportionate?','A remembered train stop opens into an expanding experience of landscape and birdsong.','The speaker conducts a complete county bird survey.','A battle destroys the station before the train arrives.','Start from reported events, then explain the movement of attention.','Separate what occurs from a literalised version of the ending’s expansion.'],practice:[['What situation is established?','A remembered unusual train stop in June.','A child’s first flight on a military mission.','An argument with a newspaper editor.','Literal orientation should precede a complex symbolic claim.','literal'],['What does repeated distance contribute?','The sense of sound spreading beyond the immediate stop.','A verified number of every bird in the region.','Proof that the speaker is no longer remembering.','Repetition changes the scale of perception.','methods'],['Which claim is a defensible inference?','The moment’s quiet attention becomes valuable in memory.','The train is proved to be the last train ever built.','Everyone at the platform shares an identical thought.','An inference should follow from the selected details without inventing facts.','inference']],check:[['What changes across the poem?','Attention widens from a station name to surrounding sound.','A reported war ends in a military parade.','The speaker stops using memory and becomes omniscient.','Track the organisation of perception rather than invent a new plot.','movement'],['Why begin with a plain summary?','It checks literal understanding before an interpretation is developed.','It replaces the need to analyse any choice.','It proves only one reading is possible.','A baseline account allows later claims to be tested.','reading'],['Which statement over-literalises the ending?','The speaker has counted and identified every bird in both counties.','The closing repetition expands a remembered soundscape.','The first-person voice recalls an earlier moment.','Poetic scope is not automatically scientific measurement.','inference'],['What should a second reading do?','Test and refine the first account through details and changes.','Add a memorised context fact whether relevant or not.','Ignore anything that complicates the initial idea.','Critical reading remains answerable to the whole text.','reading']],writing:'How does Thomas make a brief stop significant in Adlestrop? Begin with an accurate account of the situation, then analyse how attention and sound develop.',rubric:['Establish a clear, accurate literal account before developing an interpretation.','Analyse selected wording and a change in scale through the full poem.','Keep inferences proportional to the speaker’s recollection.']}),
make({topic:'unseen',key:'lesson-02',title:'Voice, tone and shifts',scope:'Up-Hill',author:'Christina Rossetti',textKeys:['uphill'],
 cards:[['Hear two positions in one poem','Read the alternating questions and answers aloud. The questioner worries about a journey and its destination; the answering voice repeatedly offers assurance. Neither voice needs to be identified as a literal named person. Tone develops through their relation, not only through an adjective attached to one isolated line.'],['Distinguish literal travel and possible allegory','The road, day and inn create a coherent journey. They can also support a reading about life, death and spiritual rest. Explain how the pattern of questioning and promised welcome makes that reading plausible. Do not claim every road in every poem must represent death, or that interpretation requires invented biography.'],['Track what changes and persists','Anxiety moves from duration towards recognition, entry and comfort. The final welcome broadens beyond the individual questioner. Compare an early question with a later reply and explain what the reassurance answers. A voice can remain concerned while an answering voice creates a growing sense of hospitality.']],details:[['Questions and replies','Alternation gives uncertainty an answering voice.'],['Road and inn','A literal journey can sustain an extended symbolic reading.'],['All who come','The close broadens the promised welcome.']],people:[['Questioner','Seeks reassurance about effort and acceptance.'],['Answering voice','Offers knowledge and hospitality.'],['Reader','Tests literal and symbolic levels together.']],movement:[['Duration','How long will the effort last?'],['Destination','Will shelter be recognisable?'],['Company','Will others have arrived before?'],['Welcome','Will the traveller be accepted?']],challenge:['Which reading connects voice and possible symbolism?','Alternating anxiety and assurance can make a journey suggest a larger passage towards rest.','A road always proves a poem has only one religious meaning.','Two voices mean the poem has no coherent relationship.','A symbolic reading needs support from the journey and its developing dialogue.','Explain how the replies respond to particular concerns before declaring a fixed meaning.'],practice:[['What defines the voices’ relation?','Questions about a journey receive reassuring replies.','One speaker gives a complete military order.','The poem consists only of unanswered statements.','Dialogue creates two positions without needing named characters.','voice'],['How can a spiritual reading be supported?','Connect the journey and welcome with the developing pattern of questions.','Announce that every inn is literally heaven in all poems.','Invent a conversation from the poet’s childhood.','A larger meaning must arise from this poem’s choices.','methods'],['What broadens at the ending?','The welcome includes all who arrive.','The exact date of a named battle.','The list of people refused at the inn.','A final inclusive reply changes the scope of reassurance.','shift']],check:[['What changes in the questions?','Concerns move from duration towards entry and comfort.','The questioner becomes a newspaper editor.','All questions concern the same train timetable.','Tracing questions shows the development of anxiety.','movement'],['Which statement keeps interpretation open?','A literal journey can also support a reasoned allegorical reading.','Only one symbol is possible because the title names a slope.','The literal journey must be ignored before analysis can begin.','Levels of meaning can coexist when connected through evidence.','interpretation'],['How should tone be explained?','Through wording and the relation between the voices.','By naming one feeling without evidence.','By assuming the poet and questioner are always identical.','Tone is a represented attitude whose development needs support.','tone'],['What is a useful pairing of evidence?','An early anxious question beside a later inclusive reply.','Two unrelated birth dates.','A single adjective copied with no explanation.','A pairing can reveal how the relation develops.','evidence']],writing:'How does Rossetti develop uncertainty and reassurance in Up-Hill? Analyse the dialogue and consider a supported larger meaning for the journey.',rubric:['Distinguish the questioner’s concerns from the replying voice.','Explain a shift through precise language or dialogue structure.','Support a symbolic interpretation without replacing evidence with a fixed code.']}),
make({topic:'unseen',key:'lesson-03',title:'Language, form and structure',scope:'The Darkling Thrush',author:'Thomas Hardy',textKeys:['thrush'],minutes:30,
 cards:[['Relate details to a developing impression','First establish the speaker at a winter gate. Images of exhaustion, broken music and death make a landscape carry a human mood. Read one detail closely: what associations does it transfer, and what does the surrounding sentence permit you to infer? A description of gloom is not proof that all nature literally shares a human mind.'],['Analyse the arrival within the frame','Four eight-line stanzas provide a patterned setting for a sudden bird voice. The frail bird’s forceful song complicates the speaker’s earlier impression. Compare the turning moment with the pattern around it. Counting stanzas can locate a shift, but counting alone does not explain its significance.'],['Let uncertainty shape the conclusion','The ending imagines a hope the bird may know while the speaker remains unaware. A defensible reading sees a challenge to despair without claiming a guaranteed conversion to confidence. Test any thesis against that final distance between the speaker and the bird’s apparent knowledge. Lyres are stringed instruments; evensong is evening worship.']],details:[['broken lyres','A damaged musical instrument makes landscape suggest failed expression or energy.'],['At once','An abrupt arrival changes the earlier sensory field.'],['I was unaware','The close leaves a distance between apparent song and human knowledge.']],people:[['Speaker','Projects and questions an exhausted view.'],['Thrush','Sings with force despite physical frailty.'],['Reader','Tests whether the ending resolves or complicates the earlier mood.']],movement:[['Scene','Establish an exhausted winter impression.'],['Projection','Relate landscape to human mood.'],['Arrival','Hear a competing force in the song.'],['Uncertainty','Read the ending’s limit on knowledge.']],challenge:['Which reading accommodates the final uncertainty?','The song challenges despair without proving that the speaker fully shares its apparent hope.','The speaker explicitly declares complete certainty and permanent joy.','The bird’s frailty means its song has no force.','An ending can unsettle an earlier view without resolving it entirely.','Compare the bird’s apparent knowledge with what the speaker says he does not know.'],practice:[['What is the visible stanza arrangement?','Four eight-line stanzas.','Seven six-line stanzas.','A single fourteen-line sonnet.','Name the frame before explaining the turn within it.','form'],['Why analyse the broken-instrument comparison?','It connects a physical landscape to impaired energy or expression.','It proves a literal orchestra is playing at the gate.','It removes the poem’s human perspective.','A figurative comparison transfers associations within a specific mood.','methods'],['What qualifies the ending’s hope?','The speaker does not claim to possess the bird’s apparent knowledge.','The speaker says the bird never sang.','The final lines erase all earlier gloom as a factual mistake.','Interpret possibility and distance rather than invent certainty.','ending']],check:[['What disrupts the initial impression?','A frail bird’s powerful song.','A train arriving at Adlestrop.','An editor choosing photographs.','The new sensory event complicates the speaker’s projection.','movement'],['Which statement is analytical?','The patterned frame makes the song’s abrupt entry a significant contrast.','There are stanzas, so there is a technique.','Regular verse always means happiness.','Connect formal organisation with a particular change.','methods'],['What claim should the final lines prevent?','The speaker has certainly acquired the same confident hope he imagines in the bird.','The song creates a pressure on the opening mood.','The reader can discuss a possible spiritual dimension.','A possible reading must respect the speaker’s declared limit.','interpretation'],['How should a word such as evensong be used?','Explain its associations in the context of the bird’s song.','Treat the term as proof of an explicit church service at the gate.','Ignore the poem and list every meaning in a dictionary.','Meaning depends on how a word functions in this passage.','language']],writing:'How does Hardy use language and poetic organisation to complicate the speaker’s view in The Darkling Thrush? Trace the bird’s arrival and test your argument against the ending.',rubric:['Develop an argument that follows the changing impression.','Analyse precise language and a structural turn rather than list devices.','Preserve the final uncertainty about hope and knowledge.']}),
make({topic:'unseen',key:'lesson-04',title:'Independent unseen analysis',scope:'Teaching model: There Will Come Soft Rains',author:'Sara Teasdale',textKeys:['rains'],minutes:35,
 cards:[['Practise separating scene and implication','In the teaching poem, vivid natural life is set beside the possibility of human disappearance. Establish the literal images before asking what their indifference implies. The poem is a model for a reading process; the independent task supplies a different complete poem, so these notes are not its answer.'],['Plan around a change','A close analysis should explain how a poem develops, not simply attach one device to each line. In the teaching model, compare early sensory abundance with the later reference to war and absence. State a tentative claim, select a detail, then test it against the ending.'],['Write first, then revise with criteria','Enter the independent workspace for a fresh practice text. The full poem remains visible while explanations and review criteria are hidden. Submit a first response before reviewing it; later revisions preserve the original. No automatic essay mark is assigned. Familiarity with a poem varies, so tell a teacher if the task is no longer unfamiliar.']],details:[['Sensory abundance','Notice sound, colour and movement before deciding their implication.'],['Human absence','The conditional possibility changes the stakes of the scene.'],['Closing perspective','Test whether nature is made to share a human response.']],people:[['Poetic voice','Imagines a world continuing beyond human conflict.'],['Human reader','Can feel the ethical pressure of apparent indifference.'],['Independent writer','Applies the reading process to a different supplied poem.']],movement:[['Orient','Identify the literal scene.'],['Trace','Notice a change in the poem’s implications.'],['Plan','Relate a precise method to a claim.'],['Attempt','Write separately on a fresh supplied text.']],challenge:['Which approach prepares independent analysis?','Practise a reading process, then test it on the new text rather than copy the model’s interpretation.','Assume every unfamiliar poem has the teaching poem’s meaning.','Replace the first response with a memorised model essay.','A transferable method is different from a predetermined answer.','Ask what the new poem actually does before applying a learned interpretation.'],practice:[['What belongs in an initial reading?','An accurate account of the scene and speaking position.','An unsupported claim about the author’s secret motive.','A fixed grade before writing.','Interpretation begins with attention to the text.','reading'],['What makes a method explanation useful?','It links a precise choice to this poem’s developing meaning.','It only names a technique.','It gives every nature image the same effect.','Analysis needs a local relation between choice and meaning.','methods'],['What should a first independent submission preserve?','The student’s own response before guided revision.','A copied replacement paragraph.','Only the final edited version with no earlier record.','A separate first response makes later improvement reviewable.','independence']],check:[['What should an answer follow?','The particular question and the supplied text’s development.','The same interpretation used for every poem.','Only the longest quotation.','Relevance depends on the actual task and evidence.','argument'],['Which evidence use is strongest?','A short accurate quotation explained through its context.','An invented quotation that fits the claim.','A long copied passage with no reasoning.','Precision and explanation make evidence useful.','evidence'],['When should criteria be used for supported revision?','After submitting the first independent response.','Instead of attempting a first response.','As proof that a saved word count is a grade.','Keep initial performance distinct from later support.','revision'],['What can this app establish about the writing?','It saves a first response and revisions for review.','It awards an official GCSE essay grade automatically.','It prevents every possible use of external resources.','Storage and recorded departures do not replace human assessment.','assessment']],writing:'Use the teaching poem to practise a brief plan, then attempt the separate unfamiliar poem in the independent workspace.',rubric:['Answer the supplied question with a coherent interpretation of the complete poem.','Explain precise language and a change in organisation using accurate evidence.','Review support, alternative implications and accurate expression after the first submission.'],contextReading:[{url:readings.barter.url,label:'Barter · source and public-domain text'}],independent:{independentWriting:true,independentTaskType:'unseen-analysis',independentTaskLabel:'An unfamiliar-poem response with the complete text supplied.',independentIntro:'Use the complete supplied poem. Develop your own reading before checking the review criteria.',independentPrompt:'How does Teasdale present what makes life valuable in Barter? Write about the language and organisation of the poem, using evidence to support your response. Original unfamiliar-reading practice, not an official exam paper.',independentExtractLabel:'Barter — Sara Teasdale · complete public-domain poem',independentExtract:wholeReading('barter')}}),
make({topic:'unseen',key:'lesson-05',title:'Comparing unseen poems',scope:'Remember / I Look into My Glass',author:'Christina Rossetti / Thomas Hardy',textKeys:['remember','glass'],minutes:30,
 cards:[['Read each voice before pairing','Rossetti’s speaker addresses someone who may outlive them; Hardy’s speaker considers a mismatch between ageing appearance and persistent feeling. Establish each situation independently. Both concern change and feeling, but a comparison loses precision if it declares their speakers identical or invents a shared conversation.'],['Compare how a position is revised or resisted','Remember turns from requesting remembrance towards concern for the survivor’s happiness. I Look into My Glass contrasts what time takes with what it leaves. Relate the sonnet’s turn to Hardy’s continuing mismatch, explaining the different work of organisation. Do not use a shared theme to erase their distinct priorities.'],['Write through the relation','Choose a short detail from each full poem and explain one useful connection with a difference. Comparative writing can move between texts within a paragraph when it serves the argument. The aim is a reasoned relation between methods, not a rule that every paragraph must contain the same number of quotations.']],details:[['Address and reflection','An addressed survivor differs from a speaker examining himself.'],['A changing request','A turn can redirect a speaker’s priorities.'],['Part taken, part left','A contrast can make an emotional difficulty persist.']],people:[['Remember speaker','Reconsiders what the survivor should carry.'],['Glass speaker','Wishes feeling would change with appearance.'],['Comparative reader','Explains relation without imposing identical motives.']],movement:[['Orient separately','Identify each speaker and situation.'],['Find a relation','Focus on change and persistent feeling.'],['Pair methods','Connect a turn with a continuing contrast.'],['Qualify','Explain the speakers’ different priorities.']],challenge:['Which comparison preserves a significant difference?','One speaker revises a request for the survivor, while the other remains troubled by a mismatch within himself.','Both speakers directly order the same person to forget them.','Both poems guarantee that ageing removes all feeling.','A shared concern develops through different speaking positions and structures.','Identify who is addressed and whose difficulty the ending prioritises.'],practice:[['What should precede a comparative claim?','A clear account of each poem’s speaker and situation.','An assumption the poems have one author.','Only a list of dates.','Accurate separate understanding supports a precise relation.','reading'],['How can organisation be compared?','Relate a change of request to a contrast that persists.','Assume a sonnet always means the speaker is happy.','Count lines without considering the argument.','Form matters through the direction of thought.','methods'],['What is the purpose of linked evidence?','To develop a relation and explain a significant difference.','To prove identical emotions by using equal quotation lengths.','To avoid discussing the question.','A comparison is an argument, not a layout formula.','comparison']],check:[['What changes in Remember?','The speaker allows forgetting if it protects the survivor’s happiness.','The speaker forbids every possibility of happiness.','The speaker becomes the author of the second poem.','A later turn qualifies the initial request.','movement'],['What troubles the Glass speaker?','Aging appearance does not remove persistent feeling.','His literal mirror has been stolen.','Time has removed all emotional response.','The bodily and emotional changes do not move together.','meaning'],['Which comparison explains methods?','A sonnet turn redirects concern, while a repeated contrast sustains a mismatch.','Both contain words, so both mean the same.','Only the titles matter.','Relate organisation to the different movements of thought.','methods'],['What should a strong conclusion retain?','The relation and the speakers’ different priorities.','A claim that all poems about loss are identical.','An invented shared biography.','Critical comparison preserves distinction as well as connection.','comparison']],writing:'Compare how Remember and I Look into My Glass present feelings that remain as life changes. Analyse the speaking positions and the organisation of thought in both complete poems.',rubric:['Establish accurate separate situations before developing a comparison.','Explain linked methods with evidence from both supplied poems.','Sustain a significant difference in priorities rather than equate the speakers.']}),
make({topic:'unseen',key:'lesson-06',title:'Timed unseen pair and revision',scope:'Planning model: Remember / I Look into My Glass',author:'Christina Rossetti / Thomas Hardy',textKeys:['remember','glass'],minutes:45,
 cards:[['Allocate time to different kinds of reading','Use the previous pair as a planning model. First form an interpretation of one complete poem; then reread the second for a precise relationship between methods. These are distinct tasks. A short comparison needs focus more than a second full essay. The independent workspace supplies a different pair.'],['Use a flexible practice budget','For the independent task, try about35minutes for the single-poem response and 10 minutes for the comparison, including rereading and a brief final check. This is a suggested practice budget, not an enforced countdown or an official section timing rule. Adjust with a teacher for access needs and lesson length.'],['Review evidence of improvement','Submit both responses before reading the review criteria. Afterwards, identify one unsupported claim, one method needing explanation and one comparison needing a sharper difference. Save a revision separately. Reusing these poems later practises revision; once encountered, they cannot be claimed as genuinely unfamiliar to that student.']],details:[['Task distinction','Single-poem interpretation and comparison need different focuses.'],['Rereading','Use the second reading to test relations, not only find matching topics.'],['Revision evidence','Preserve changes in reasoning between first response and revision.']],people:[['Writer under time','Chooses relevant evidence and a manageable argument.'],['Revising reader','Tests support after the unassisted attempt.'],['Teacher','Calibrates timing and reviews actual responses.']],movement:[['First response','Analyse one supplied poem.'],['Second response','Compare a focused method relationship.'],['Submit','Preserve both unassisted responses.'],['Revise','Make a separate supported improvement.']],challenge:['Which plan distinguishes the two tasks?','Analyse the first poem, then make a focused comparison of methods with the second.','Write the same full essay twice with new titles.','Treat a shared topic as sufficient method analysis.','Different task demands require a deliberate allocation of attention.','Ask what the comparison adds rather than repeating the single-poem account.'],practice:[['What should a short comparative response prioritise?','A precise relation between methods and meanings.','An unrelated biography of each poet.','A second complete summary without a relation.','Focus helps a shorter task remain analytical.','comparison'],['How should the practice timing be treated?','As an adjustable suggested budget, not an enforced exam rule.','As an automatic submission deadline controlled by this app.','As a guarantee of the same pace for every student.','Timing practice should be explicit and proportionate to access needs.','planning'],['What makes a revision visible?','A saved first response and separate revised reasoning.','Deleting the original so only word count remains.','Copying guidance without reconsidering evidence.','An inspectable change helps a teacher discuss improvement.','revision']],check:[['What should occur before review criteria are revealed?','Submission of the first response.','Automatic essay grading from a click score.','Replacement with a model paragraph.','Separate initial performance from supported revision.','independence'],['Which comparison is method-led?','Explain how different choices shape a related experience.','State both poems mention a feeling and stop.','List shared nouns with no analysis.','Comparison concerns the work of choices, not only shared content.','methods'],['What does encountering the poems change?','A later attempt is revision or retrieval rather than genuinely unfamiliar reading.','The poems become official AQA questions.','Every later reading automatically earns mastery.','Familiarity must be reported honestly.','assessment'],['What can a final edit improve?','Clarity, evidence accuracy and the logic of the relation.','The official mark automatically awarded here.','The author’s original wording by silently replacing it.','Editing should improve the student’s argument without falsifying evidence.','accuracy']],writing:'Practise a focused plan using the earlier pair. Use the independent workspace for the separate single-poem and comparison tasks on a fresh pair.',rubric:['Develop a supported reading of Sympathy through precise methods and the whole poem.','Compare how both supplied poems use bird or song imagery, explaining a significant difference.','Revise coherence, evidence accuracy and expression after preserving the first response.'],contextReading:[{url:readings.hope.url,label:'Hope · early edited source version'},{url:readings.sympathy.url,label:'Sympathy · complete poem source'}],independent:{independentWriting:true,independentTaskType:'unseen-pair',independentTaskLabel:'A single-poem response followed by a comparison of two supplied poems.',independentIntro:'Use the two complete supplied poems. Suggested practice: 35 minutes for task1 and 10 minutes for task2; timing is not enforced. Write both responses before submitting.',independentPrompt:'Task 1: How does Dunbar present the bird’s experience in Sympathy? Analyse language and organisation. Task 2: Compare the ways Dunbar and Dickinson use bird or song imagery in Sympathy and Hope. Focus on methods and their effects. Label your two responses. Original practice, not an official exam paper.',independentExtractLabel:'Two complete public-domain poems · Hope uses the early edited 1891 text',independentExtract:wholeReading('sympathy','hope')}}),
make({topic:'reading-writing',key:'lesson-01',title:'Literal meaning and inference',scope:'Macbeth · Act1, scene3',author:'William Shakespeare',sources:[folger('1/3')],quote:'He bade me, from him, call thee Thane of Cawdor,',sourceNote:'Brief public-domain Shakespeare wording, checked against Macbeth1.3 in the Folger text. Original teaching commentary; read the complete scene. Line numbering varies by edition.',
 cards:[['Make two different kinds of claim','Ross reports Duncan’s instruction to give Macbeth the Cawdor title. That is explicit information. Macbeth’s response can support an inference about how he experiences promotion, but an inference is not another fact spoken by Ross. Keep the source of each claim visible: who says it, and what does the wording establish?'],['Use a scale of confidence','A useful reading can distinguish a secure observation, a plausible inference and a speculation needing more evidence. Macbeth’s interest in the prophecies develops across the scene. A title alone does not prove he has already decided to murder Duncan. Later evidence can strengthen or qualify an earlier tentative reading.'],['Test against a contrary detail','Before writing, ask what would make the inference less certain. If a claim relies on one phrase, read the surrounding exchange and a later relevant moment. Qualifying verbs such as suggests or may matter when uncertainty is real; adding them to an invented fact does not make it supported.']],details:[['He bade me','The report identifies an instruction rather than Macbeth’s private thought.'],['from him','The authority behind the message is Duncan’s.'],['Thane of Cawdor','The announced reward is distinct from the future kingship prophecy.']],people:[['Ross','Reports the king’s decision.'],['Macbeth','Responds while considering the prophecies.'],['Reader','Separates stated information from inferred motivation.']],movement:[['Locate','Name speaker and moment.'],['State','Record what is explicit.'],['Infer','Develop a proportional interpretation.'],['Test','Read context and a possible qualification.']],challenge:['Which claim keeps fact and inference distinct?','The title is explicitly announced; Macbeth’s reaction needs interpretation in context.','The announcement proves Macbeth has already committed Duncan’s murder.','Calling an invented event a possibility makes it evidence.','A textual statement and an inferred motive have different levels of certainty.','Ask whether the words actually establish the event or only support a reading of response.'],practice:[['Which information is explicit?','Ross announces the Cawdor title.','Macbeth has already killed Duncan at this moment.','Ross reports Macbeth’s every private thought.','Identify what is actually spoken in this scene.','literal'],['What makes an inference defensible?','A proportionate claim supported by wording and context.','A dramatic possibility with no textual support.','Only adding perhaps to an invented event.','Qualification cannot replace evidence.','inference'],['How can later evidence be used?','To strengthen or qualify the reading without changing the earlier event.','To pretend Macbeth knew every later outcome already.','To erase the scene’s sequence.','Track development without projecting certainty backwards.','context']],check:[['What distinction should an argument retain?','Reported information differs from inferred private motive.','Every statement about a character is equally explicit.','All first impressions are automatically false.','A reasoned interpretation distinguishes kinds of knowledge.','reading'],['Which statement overclaims?','Receiving a title proves a settled decision to kill the king.','A promotion can affect Macbeth’s response to prophecy.','The surrounding exchange helps interpret a reaction.','The reward does not by itself establish a future decision.','inference'],['Why identify the speaker?','It clarifies whose knowledge or claim the evidence supplies.','It makes context and sequence unnecessary.','It proves the speaker is always the poet.','Evidence belongs to a particular speaking position.','voice'],['What should a qualification do?','Reflect a real limit in the evidence.','Hide the absence of any evidence.','Make every interpretation impossible to argue.','A qualified claim can remain clear and purposeful.','argument']],writing:'Explain what Ross’s announcement establishes and what Macbeth’s response allows us to infer in Act1, scene3. Use a surrounding detail to test the strength of the inference.',rubric:['Separate explicit information from inferred motive.','Support the inference through accurate context and wording.','Qualify confidence where the evidence genuinely leaves alternatives.']}),
make({topic:'reading-writing',key:'lesson-02',title:'Selecting and integrating evidence',scope:'Macbeth · Act1, scene7',author:'William Shakespeare',sources:[folger('1/7')],quote:'He’s here in double trust:\nFirst, as I am his kinsman and his subject,\nStrong both against the deed; then, as his host,\nWho should against his murderer shut the door,\nNot bear the knife myself.',sourceNote:'Brief public-domain Shakespeare passage from Macbeth1.7; original commentary. Quotation apostrophes are typographically normalised. Consult the whole scene for the debate and its changes.',
 cards:[['Choose the evidence for the claim','To argue that Macbeth recognises obligations towards Duncan, the trust passage is more relevant than a distant line selected only because it is memorable. Name the relationship you are discussing, then choose the smallest detail that lets you explain it. Evidence should serve the question rather than display how much you can recall.'],['Integrate wording into your own reasoning','A sentence might argue: Macbeth recognises overlapping duties when he describes Duncan as being in double trust. For a direct quotation, put the exact borrowed words in quotation marks and make the grammar of your sentence work around them. A paraphrase is useful too, but must not be presented as the playwright’s exact wording.'],['Do not change the evidence to fit','Keep the speaker, scene and wording accurate. If omitting material, do not remove a qualification that changes the meaning. Explain the quotation after introducing it: why does the relationship matter to this decision? A short quotation can support close analysis; length alone is not a measure of evidence quality.']],details:[['double trust','Overlapping obligations become a reason against the proposed act.'],['kinsman and his subject','Family relationship and political duty are distinguished.'],['his host','Hospitality adds a further obligation of protection.']],people:[['Macbeth','Articulates reasons against killing Duncan.'],['Duncan','Occupies the roles of relative, king and guest.'],['Analytical writer','Chooses wording that supports a specific claim.']],movement:[['Claim','Name the relevant obligation.'],['Select','Choose a precise supporting detail.'],['Integrate','Fit accurate wording into a clear sentence.'],['Explain','Show why the relationship matters to the decision.']],challenge:['Which sentence uses evidence responsibly?','Macbeth’s reference to double trust supports a claim that he recognises obligations towards Duncan.','A quotation is strongest when its wording is changed to fit the argument.','The longest passage always explains itself.','Evidence must remain accurate and its relevance needs explanation.','Test wording, context and reasoning together instead of measuring quotation length.'],practice:[['What should determine evidence selection?','The claim and question being answered.','The longest line the student remembers.','A requirement to quote every scene.','Relevance is a relationship between evidence and argument.','selection'],['How should paraphrase be presented?','As the student’s own accurate account, without pretending it is an exact quotation.','In quotation marks as Shakespeare’s exact words.','With invented wording attributed to a speaker.','Distinguish borrowed wording from a summary of meaning.','references'],['What should follow an integrated quotation?','Explanation of how it supports the claim.','An assumption that length proves analysis.','An unrelated context fact.','The writer supplies the reasoning the evidence needs.','reasoning']],check:[['Which relationship is relevant in the trust passage?','Macbeth’s obligations as relative, subject and host.','Duncan’s job as Macbeth’s editor.','The witches’ status as Duncan’s children.','Accurate context makes the selected evidence meaningful.','context'],['What is an evidence error?','Silently removing a qualification that changes the meaning.','Quoting a short precise phrase accurately.','Identifying the speaker and scene.','Selection must not falsify the source.','accuracy'],['What makes integration clear?','The quotation fits the grammar and reasoning of the student’s sentence.','The quotation is placed alone with no claim.','Several long passages are copied before the question is considered.','A quotation should function within an argument.','writing'],['Which measure cannot establish evidence quality?','The quotation’s length by itself.','Its accuracy.','Its relevance to the claim.','Quality depends on support and explanation, not word count alone.','selection']],writing:'Write a paragraph arguing that Macbeth recognises obligations towards Duncan. Integrate one short accurate quotation, explain its significance and connect it to the decision in Act1, scene7.',rubric:['Select evidence relevant to the stated obligation.','Integrate exact wording or clearly distinguish an accurate paraphrase.','Explain significance in context using clear grammar and punctuation.']}),
make({topic:'reading-writing',key:'lesson-03',title:'Methods and effects',scope:'Macbeth · Act2, scene1',author:'William Shakespeare',sources:[folger('2/1')],quote:'Is this a dagger which I see before me,\nThe handle toward my hand? Come, let me clutch thee.\nI have thee not, and yet I see thee still.',sourceNote:'Brief public-domain Shakespeare passage, Macbeth2.1, checked against the Folger text. Original analysis; performance choices and interpretations may differ.',
 cards:[['Begin with a precise observation','Macbeth questions a visible dagger, reaches towards it and cannot grasp it. Notice the contradiction before naming a technique. An analysis might connect questions, imperatives and opposing sensory claims to unstable confidence. A device name is useful when it helps specify what changes or becomes uncertain.'],['Explain a possible effect through the situation','The audience encounters Macbeth testing perception before the murder. A production can show the dagger or leave it unseen, so do not claim every audience receives identical visual proof of magic. Explain how the language makes seeing, touching and intention difficult to separate, then consider what a staging choice changes.'],['Avoid the automatic effect formula','A question does not always make every reader curious; an imperative does not always establish successful control. Link the feature to this speaker, moment and surrounding contradiction. The best explanation shows a chain from wording to meaning and a qualified possible response, not an unsupported claim that the audience must feel one emotion.']],details:[['Is this','A question tests the status of what seems visible.'],['let me clutch','An attempt to act meets the limits of touch.'],['not ... yet','Opposed claims keep perception unsettled.']],people:[['Macbeth','Tests an experience he cannot securely grasp.'],['Director','Chooses how much the audience can see.'],['Audience','Interprets language alongside a particular staging.']],movement:[['Observe','Describe a precise choice.'],['Locate','Connect it with speaker and moment.'],['Explain','Show how it shapes meaning.'],['Qualify','Consider a possible response or staging difference.']],challenge:['Which statement analyses a method in context?','The conflict between seeing and touching unsettles the certainty of Macbeth’s perception.','Every question makes all audiences react identically.','Naming an imperative proves Macbeth controls the dagger.','A method’s significance depends on its work within this situation.','Follow the contradiction between attempted action and uncertain perception.'],practice:[['What should precede a device label?','A precise observation of wording or organisation.','An invented audience survey.','A claim the method always has one effect.','A label clarifies analysis only when attached to something specific.','methods'],['What does the sensory contradiction permit?','A reading of perception becoming difficult to trust.','Proof that the dagger is physically real in every production.','Certainty that Macbeth has no intention at all.','The language holds competing kinds of evidence together.','inference'],['How should audience response be phrased?','As a reasoned possibility connected with language and staging.','As an identical compulsory feeling for everyone.','As a substitute for any textual evidence.','Responses can differ while remaining accountable to the performance.','response']],check:[['Which sentence moves beyond naming?','Opposing sensory claims make certainty difficult at this moment.','There is a question mark.','Shakespeare uses a technique.','Explain what the choice does, not only what it is called.','reasoning'],['What can a staging choice change?','Whether the audience sees the dagger Macbeth describes.','The exact words Shakespeare wrote.','The fact that every audience must believe in magic.','Performance supplies a perspective on the speech’s uncertainty.','performance'],['Which effect claim needs correction?','An imperative always proves the speaker’s successful control.','An attempted action can reveal a limit.','Context can complicate a command’s significance.','A grammatical form does not guarantee its intended outcome.','methods'],['What makes an explanation coherent?','A chain linking detail, context, meaning and a qualified response.','A list of terms with no connections.','A prediction of every spectator’s private thoughts.','Reasoning makes the relation between observation and interpretation explicit.','argument']],writing:'Analyse how the dagger speech makes Macbeth’s perception uncertain. Explain two connected choices and consider how a production could affect the audience’s access to the experience.',rubric:['Identify precise choices rather than list technique names.','Explain how language develops uncertainty in this dramatic moment.','Qualify audience effects and distinguish text from staging interpretation.']}),
make({topic:'reading-writing',key:'lesson-04',title:'Context and alternative interpretations',scope:'Macbeth · Act1, scene7',author:'William Shakespeare',sources:[folger('1/7')],quote:'First, as I am his kinsman and his subject,\nStrong both against the deed; then, as his host,',sourceNote:'Brief public-domain Shakespeare wording, Macbeth1.7. Original teaching interpretations; contextual possibilities are not compulsory beliefs of every historical spectator.',
 cards:[['Make context explain a textual pressure','Macbeth’s references to being subject, relative and host make political, family and hospitality obligations relevant to the murder debate. Context is useful when it explains why a choice may matter. It should not become an unrelated history paragraph or a claim that every Jacobean spectator held the same view.'],['Compare alternatives through evidence','One reading emphasises moral recognition: Macbeth understands reasons against killing. Another stresses self-protective calculation when the larger speech considers consequences. These readings can coexist or compete. Explain what each foregrounds and which surrounding details strengthen it, instead of declaring all interpretations equally supported.'],['Return to the scene’s development','The debate does not end when one obligation is named. Read the shifts in decision and pressure across the scene. A good evaluation can judge that moral awareness is present without assuming it guarantees moral action. Alternative readings should refine a claim through evidence, not distract from answering the question.']],details:[['subject','Political duty becomes part of the decision’s pressure.'],['kinsman','A personal relationship complicates the planned violence.'],['host','An obligation to protect the guest conflicts with the proposed act.']],people:[['Macbeth','Recognises obligations while considering action and consequences.'],['Historical spectators','Could bring differing beliefs and experiences to the performance.'],['Critical reader','Weighs alternatives against precise scene evidence.']],movement:[['Connect','Find a context made relevant by words.'],['Propose','State a supported interpretation.'],['Compare','Test an alternative against other details.'],['Evaluate','Refine the claim through the scene’s development.']],challenge:['Which use of context is most responsible?','Explain how obligations named in the speech make the contemplated act more troubling.','Assume every historical spectator thought identically.','Replace the scene with an unrelated royal biography.','Context should illuminate a pressure the text actually presents.','Begin with the named relationship and ask what it contributes to the debate.'],practice:[['What makes context relevant?','A connection to a precise choice or pressure in the text.','Its length regardless of the question.','A claim about every spectator’s identical beliefs.','Context supports analysis when its relationship with evidence is explained.','context'],['How should alternatives be evaluated?','Weigh their supporting details and limitations.','Treat every invented account as equally valid.','Reject any reading that differs from the first idea.','Interpretive openness still requires evidence.','interpretation'],['What does recognised duty not guarantee?','That Macbeth will act in accordance with it.','That the speech names an obligation.','That a reader can analyse a conflict.','Awareness and conduct are distinct.','inference']],check:[['What is an example of connected context?','Relating hospitality to Macbeth’s reference to being Duncan’s host.','Listing dates with no relation to the speech.','Using biography to prove every motive.','The wording makes a social obligation part of the dramatic problem.','context'],['Which pair of readings can be tested?','Moral recognition and concern about personal consequences.','A literal newspaper editor and an unnamed train driver.','Two invented scenes with no textual basis.','Competing emphases should arise from the speech and its context.','interpretation'],['Why consider the whole scene?','A later pressure or decision can qualify an earlier statement.','A single phrase always proves every later action.','Context removes the need to follow events.','Development matters to the strength of an interpretation.','structure'],['Which evaluation is proportionate?','Moral awareness is present, though it does not ensure moral action.','Recognising duty proves the murder cannot occur.','Every interpretation has exactly the same support.','A clear judgment can preserve a genuine tension.','argument']],writing:'Evaluate the view that Macbeth’s hesitation in Act1, scene7 shows moral awareness. Use connected context and test an alternative emphasis on personal consequences.',rubric:['Connect contextual understanding to precise textual relationships.','Weigh an alternative reading through supporting details and limits.','Reach a clear qualified judgment that follows the scene’s development.']}),
make({topic:'reading-writing',key:'lesson-05',title:'An analytical paragraph',scope:'Macbeth · Act1, scene4',author:'William Shakespeare',sources:[folger('1/4')],quote:'Stars, hide your fires;\nLet not light see my black and deep desires.',sourceNote:'Brief public-domain Shakespeare passage, Macbeth1.4. Worked reasoning is original commentary and must not be quoted as Shakespeare’s words.',
 cards:[['Give the paragraph a job','A paragraph should develop a claim relevant to the question. To discuss concealed ambition, a claim might focus on the gap between public loyalty and private desire. Select the short appeal to hidden light because it bears on concealment, not because every paragraph must contain a predetermined number of quotations.'],['Make the reasoning visible','A worked step: Macbeth asks for light to be hidden, imagining desire as something exposure would reveal. The contrast can make ambition seem both powerful and troubling to him. This is teaching commentary, not a play quotation. Improve it by explaining how the private speech changes what the audience knows compared with other characters.'],['Revise the support, then the expression','Check whether the final sentence develops the opening claim. Remove a claim that the evidence cannot establish; qualify what remains uncertain. Then edit quotation accuracy, sentence boundaries and punctuation. An acronym can remind a writer of useful moves, but it should not turn reasoning into a fixed sentence count or replace a personal argument.']],details:[['hide','An appeal for concealment gives the desire a private setting.'],['light see','Personification imagines exposure as an act of observation.'],['black and deep','Description gives the hidden desire troubling weight without specifying every future act.']],people:[['Macbeth privately','Reveals a desire to conceal.'],['Other characters','Do not hear every private thought shared with the audience.'],['Analytical writer','Explains how wording and dramatic access support a claim.']],movement:[['Claim','Define what the paragraph will establish.'],['Evidence','Select a short relevant detail.'],['Reasoning','Explain how the choice supports the claim.'],['Revision','Test support and improve clear expression.']],challenge:['Which paragraph plan develops reasoning?','A focused claim, relevant evidence and explanation of how concealment shapes dramatic knowledge.','A quotation followed only by the word metaphor.','A fixed five sentences regardless of what the argument needs.','A paragraph is an act of supported reasoning, not an evidence container.','Check what the explanation adds between the quotation and the claim.'],practice:[['What should the opening claim do?','Define a relevant point the paragraph will develop.','Announce every theme in the play.','Promise a grade before any evidence is considered.','Focus gives later detail and reasoning a purpose.','argument'],['What is the role of a worked explanation?','To show a chain of reasoning the student can test and improve.','To supply Shakespeare’s exact additional dialogue.','To replace the need for the student’s own claim.','Teaching commentary models analysis rather than becoming textual evidence.','reasoning'],['What should revision check first?','Whether the evidence and explanation support the claim.','Only whether the paragraph has a fixed number of words.','How many unrelated context facts can be added.','Substantive support comes before cosmetic expansion.','revision']],check:[['Which statement analyses the private speech?','It gives the audience access to concealment other characters may not share.','It proves every character hears the same private wish.','It means Macbeth has already become king at this moment.','Dramatic access can create a gap in knowledge.','methods'],['What should not appear as a play quotation?','The app’s original worked explanation.','Accurately copied words from the assigned play.','A clearly attributed short phrase with correct wording.','Distinguish commentary from the primary text.','evidence'],['What makes a concluding sentence useful?','It develops or qualifies the paragraph’s claim through the analysis.','It repeats a device name without reasoning.','It introduces an unsupported unrelated fact.','A paragraph should make progress in the argument.','coherence'],['What does an acronym or sentence count fail to establish?','The quality of reasoning and support.','A possible reminder to include evidence.','The value of checking expression.','A template can help organise work but cannot prove analytical quality.','assessment']],writing:'Write one analytical paragraph on how Shakespeare presents concealed ambition in Act1, scene4. Make a focused claim, integrate precise evidence and explain the audience’s access to Macbeth’s private desire. Save a first version, then revise its support and expression.',rubric:['Develop one relevant claim rather than a list of themes.','Integrate accurate evidence and explain language and dramatic access.','Revise reasoning, qualification and sentence accuracy while preserving the first version.']})
];
